<script setup>
import { computed, onUnmounted, reactive, ref, watch } from 'vue'
import { money } from '../utils'

const props = defineProps({ open: Boolean, method: { type: String, default: 'card' }, amount: { type: Number, default: 0 }, bookingCode: { type: String, default: '' }, processing: Boolean, error: { type: String, default: '' } })
const emit = defineEmits(['close', 'confirm'])
const card = reactive({ number: '', name: '', expiry: '', cvc: '' })
const touched = ref(false)
const digits = computed(() => card.number.replace(/\D/g, ''))
const cardValid = computed(() => /^\d{16}$/.test(digits.value) && card.name.trim().length >= 3 && /^(0[1-9]|1[0-2])\/\d{2}$/.test(card.expiry) && /^\d{3,4}$/.test(card.cvc))
const qrUrl = computed(() => `https://img.vietqr.io/image/VCB-0000000000-compact2.png?amount=${Math.round(props.amount)}&addInfo=${encodeURIComponent(`STAYGO DEMO ${props.bookingCode}`)}&accountName=STAYGO DEMO`)

function formatCard(event) { card.number = event.target.value.replace(/\D/g, '').slice(0, 16).replace(/(.{4})/g, '$1 ').trim() }
function formatExpiry(event) { const value = event.target.value.replace(/\D/g, '').slice(0, 4); card.expiry = value.length > 2 ? `${value.slice(0, 2)}/${value.slice(2)}` : value }
function clearSensitive() { card.number = ''; card.name = ''; card.expiry = ''; card.cvc = ''; touched.value = false }
function close() { if (props.processing) return; clearSensitive(); emit('close') }
function confirmPayment() {
  touched.value = true
  if (props.method === 'card' && !cardValid.value) return
  emit('confirm', props.method === 'card' ? { card_last_four: digits.value.slice(-4) } : {})
}
watch(() => props.open, value => { document.body.style.overflow = value ? 'hidden' : ''; if (!value) clearSensitive() })
onUnmounted(() => { document.body.style.overflow = ''; clearSensitive() })
</script>

<template>
  <Teleport to="body"><div v-if="open" class="mock-overlay" role="dialog" aria-modal="true" aria-labelledby="payment-title" @click.self="close">
    <div class="mock-modal"><button class="mock-close" :disabled="processing" aria-label="Đóng" @click="close">×</button>
      <header><span class="mock-brand">S</span><div><p>STAYGO SECURE DEMO</p><h2 id="payment-title">{{ method === 'paypal' ? 'Mô phỏng PayPal' : method === 'card' ? 'Mô phỏng thanh toán thẻ' : 'Mô phỏng VietQR' }}</h2></div></header>
      <div class="mock-columns">
        <section class="mock-stage">
          <div v-if="method === 'paypal'" class="paypal-box"><div class="paypal-logo"><i>P</i> Pay<span>Pal</span></div><p>Đăng nhập tài khoản PayPal sandbox</p><label>Email<input value="demo-buyer@staygo.test" readonly /></label><label>Mật khẩu<input type="password" value="staygo-demo" readonly /></label><div class="demo-banner">Màn hình mô phỏng. Không kết nối PayPal và không phát sinh giao dịch thật.</div></div>
          <div v-else-if="method === 'card'" class="card-layout"><div class="visual-card"><div class="card-top"><span>STAYGO</span><b>VISA</b></div><i class="chip"></i><strong>{{ card.number || '•••• •••• •••• ••••' }}</strong><div><span>{{ card.name || 'TEN CHU THE' }}</span><span>{{ card.expiry || 'MM/YY' }}</span></div></div><div class="card-fields"><label>Số thẻ<input :value="card.number" inputmode="numeric" autocomplete="cc-number" placeholder="4111 1111 1111 1111" @input="formatCard" /></label><label>Tên chủ thẻ<input v-model.trim="card.name" autocomplete="cc-name" placeholder="NGUYEN VAN A" /></label><div><label>Hạn dùng<input :value="card.expiry" inputmode="numeric" autocomplete="cc-exp" placeholder="12/30" @input="formatExpiry" /></label><label>CVC<input v-model="card.cvc" type="password" inputmode="numeric" maxlength="4" autocomplete="cc-csc" placeholder="•••" /></label></div><small v-if="touched && !cardValid">Kiểm tra số thẻ 16 số, tên, hạn dùng và CVC.</small><p>Chỉ 4 số cuối được gửi đến API. Số thẻ đầy đủ và CVC không được gửi hoặc lưu.</p></div></div>
          <div v-else class="qr-layout"><div class="qr-card"><span>VIETQR DEMO</span><img :src="qrUrl" alt="Mã VietQR demo động" /><strong>{{ money(amount) }}</strong><small>STAYGO DEMO {{ bookingCode }}</small></div><div class="phone"><div class="phone-notch"></div><div class="phone-status"><span>9:41</span><span>5G ◉</span></div><div class="phone-camera"><span class="scan-line"></span><b>Đang quét VietQR</b><small>Camera ngân hàng giả lập</small></div><button type="button" :disabled="processing" @click="confirmPayment">{{ processing ? 'Đang xác nhận...' : 'Mô phỏng đã thanh toán' }}</button></div></div>
        </section>
        <aside><p class="eyebrow">Tóm tắt thanh toán</p><h3>Mã đặt phòng</h3><strong>{{ bookingCode }}</strong><hr /><div><span>Số tiền</span><strong>{{ money(amount) }}</strong></div><div><span>Môi trường</span><b>DEMO</b></div><p>Thao tác này chỉ xác nhận payment intent mock trên StayGo, không chuyển tiền thật.</p><p v-if="error" class="mock-error">{{ error }}</p><button v-if="method !== 'vietqr'" class="mock-confirm" :disabled="processing" @click="confirmPayment">{{ processing ? 'Đang xác nhận...' : method === 'paypal' ? 'Đăng nhập và thanh toán demo' : 'Thanh toán demo' }}</button><p v-else-if="processing" class="processing">Đang xác nhận thanh toán...</p></aside>
      </div>
    </div>
  </div></Teleport>
</template>

<style scoped>
